UPDATE curvy_dolphin.videos
SET thumbnail_url = '/temp_images/' || id || '.jpg';

SELECT
    u.user_id,
    u.username,
    COUNT(DISTINCT v.id)  AS video_count,
    COUNT(DISTINCT c.id)  AS comment_count,
    COUNT(DISTINCT l.video_id)  AS like_count
FROM curvy_dolphin.users u
LEFT JOIN curvy_dolphin.videos v    ON v.user_id = u.user_id
LEFT JOIN curvy_dolphin.comments c ON c.user_id = u.user_id
LEFT JOIN curvy_dolphin.video_likes l    ON l.user_id = u.user_id
GROUP BY u.user_id, u.username
ORDER BY u.user_id;